import sys, random, json, subprocess
sys.path.insert(0,'/workspace/tmp'); sys.path.insert(0,'/workspace')
import ref, gen

def make_doc(rng, K, nchord, maxdist, nleaf, nextra, maxcore=16):
    c = list(range(1, K+1))
    leaves = list(range(100, 100+nleaf))
    ixps = set(rng.sample(range(500, 520), rng.randint(0, 2)))
    paths = []
    base = list(c)
    for s in range(K):
        rot = base[s:] + base[:s]
        paths.append(list(rot))
    for _ in range(nchord):
        i = rng.randrange(K); d = rng.randint(2, maxdist); j = (i+d) % K
        seq = [c[i], c[j], c[(j+rng.randint(1,3)) % K]]
        paths.append(seq)
    for _ in range(nextra):
        seq = rng.sample(c, rng.randint(2, min(6, K)))
        paths.append(seq)
    rib = []
    for seq in paths:
        for rep in range(rng.randint(1, 2)):
            q = list(seq)
            if rng.random() < 0.4:
                q = q[::-1]
            if rng.random() < 0.5:
                q = [rng.choice(leaves)] + q + [rng.choice(leaves)]
            if rng.random() < 0.3:
                q = [rng.choice(leaves)] + q
            out = []
            for a in q:
                if rng.random() < 0.15: out.append(a)
                if ixps and rng.random() < 0.2: out.append(rng.choice(sorted(ixps)))
                if rng.random() < 0.1: out.append(a)
            rib.append({'path': out, 'count': rng.randint(1, 4)})
    agg = ref.aggregate([(tuple(r['path']), r['count']) for r in rib], ixps)
    _l, _r, final = ref.peel_naive(agg)
    cl = sorted({ref.canon(p[i], p[i+1]) for p in final for i in range(len(p)-1)})
    if not cl:
        return None
    if len(cl) <= maxcore:
        order = gen.exact_order(cl, final)
        if order is None:
            return None
    else:
        order = heuristic_order(cl, final)
        if order is None:
            return None
    pool = c + leaves
    priors = []; seen = set()
    for _ in range(rng.randint(0, 5)):
        u, v = rng.sample(pool, 2)
        if gen.canon_pair(u, v) in seen: continue
        seen.add(gen.canon_pair(u, v))
        w = [rng.randint(0, 4) for _ in range(3)]
        if sum(w) == 0: w[rng.randrange(3)] = 1
        priors.append({'link': [u, v], 'weights': w})
    declared = []
    for _ in range(rng.randint(0, 4)):
        u, v = rng.sample(pool, 2)
        if gen.canon_pair(u, v) in seen: continue
        seen.add(gen.canon_pair(u, v))
        declared.append({'link': [u, v], 'rel': rng.choice(['c2p','p2p','p2c'])})
    queries = []
    allp = pool + [x + 2000 for x in pool]
    for k in range(rng.randint(1, 12)):
        n = rng.randint(0, 14)
        path = [rng.choice(allp) for _ in range(n)]
        if path and rng.random() < 0.2: path.append(path[0])
        a = rng.randint(0, 10); b = rng.randint(max(1, a), 10)
        queries.append({'id': 'q%d' % k, 'path': path, 'threshold': [a, b]})
    return {'version': 1, 'ixps': sorted(ixps), 'rib': rib, 'priors': priors,
            'declared': declared, 'order': order, 'queries': queries}


def heuristic_order(core_links, final):
    m = len(core_links)
    scopes = gen.scopes_of(core_links, final)
    for attempt in range(60):
        rng = random.Random(attempt)
        adj = [set() for _ in range(m)]
        for s in scopes:
            for i in range(len(s)):
                for j in range(i+1, len(s)):
                    adj[s[i]].add(s[j]); adj[s[j]].add(s[i])
        alive = set(range(m)); order = []; width = 0; ok = True
        while alive:
            cands = sorted(alive, key=lambda v: len(adj[v] & alive))
            pick = cands[0] if rng.random() < 0.8 else rng.choice(cands[:3])
            nbrs = adj[pick] & alive
            width = max(width, len(nbrs))
            if width > 4:
                ok = False; break
            nl = list(nbrs)
            for i in range(len(nl)):
                for j in range(i+1, len(nl)):
                    adj[nl[i]].add(nl[j]); adj[nl[j]].add(nl[i])
            order.append(pick); alive.discard(pick)
        if ok:
            return [core_links[v] for v in order]
    return None


def main():
    seed = int(sys.argv[1]); count = int(sys.argv[2])
    rng = random.Random(seed); zero = 0; maxcore = 0
    for i in range(count):
        doc = None; guard = 0
        while doc is None:
            guard += 1
            if guard > 300:
                print('stuck'); return 1
            K = rng.choice([4, 5, 6, 8, 10, 12, 16, 20, 24])
            doc = make_doc(rng, K, rng.randint(0, 6), rng.randint(2, 4),
                           rng.randint(1, 4), rng.randint(0, 6),
                           maxcore=16 if K <= 12 else 10**9)
        _l, _r, final = ref.peel_naive(ref.aggregate(
            [(tuple(r['path']), r['count']) for r in doc['rib']], set(doc['ixps'])))
        cl = {ref.canon(p[j], p[j+1]) for p in final for j in range(len(p)-1)}
        maxcore = max(maxcore, len(cl))
        expected = ref.reference(doc)
        out = subprocess.run([sys.executable, '-I', 'submission/main.py'],
                             input=json.dumps(doc).encode(), stdout=subprocess.PIPE,
                             cwd='/workspace')
        try:
            actual = json.loads(out.stdout.decode())
        except Exception:
            print('BAD', out.stdout[:300]); print(json.dumps(doc)); return 1
        msg = gen.equal(expected, actual)
        if msg or out.returncode != 0:
            print('FAIL', seed, i, out.returncode, msg); print(json.dumps(doc))
            print('exp', json.dumps(expected)); print('act', json.dumps(actual)); return 1
        if expected.get('error') == 'zero-partition': zero += 1
    print('OK %d cases (%d zero-partition), max core links %d' % (count, zero, maxcore))


main()
